    public string CacheId=>"qqq_gex_wire";
    public CacheStatus Inspect(){if(IsUnavailable)return new(CacheId,"sqlite","shared data directory",0,0,null,null,null,"GEX storage unreadable; counts unknown, original file retained, writes and maintenance paused",CanClear:false);using var c=Open();using var cmd=c.CreateCommand();cmd.CommandText="SELECT COUNT(*),COALESCE(SUM(CASE WHEN expires_at<=$now THEN 1 ELSE 0 END),0),COALESCE(SUM(length(CAST(body AS BLOB))),0) FROM qqq_gex_wire";cmd.Parameters.AddWithValue("$now",DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());using var r=cmd.ExecuteReader();r.Read();return new(CacheId,"sqlite","shared data directory",r.GetInt64(0),r.GetInt64(1),null,null,r.GetInt64(2),"Exact derived wire variants; explicit expires_at and a default 64 MiB logical wire cap (48 MiB import target); gzip-protected unique history is not evicted; archive warning threshold 1 GiB, capture/import disk reserve 256 MiB; a configured wire cap up to 256 MiB is supported; oldest source times evicted first. Clearing preserves raw provider inputs, observations, full/partial days and summaries; regenerate through explicit local calculation.",SharedFileBytes:new FileInfo(new Microsoft.Data.Sqlite.SqliteConnectionStringBuilder(connectionString).DataSource).Length,RetainedBytes:RetainedStorageBytes());}
