        ReencodeLegacyArchives();using var connection=Open();using var command=connection.CreateCommand();command.CommandTimeout=5;command.CommandText="PRAGMA busy_timeout=5000";command.ExecuteNonQuery();command.CommandText="PRAGMA integrity_check";if(command.ExecuteScalar()?.ToString()!="ok")throw new InvalidDataException("GEX database is corrupt; compaction refused");
        command.CommandText="PRAGMA auto_vacuum=INCREMENTAL";command.ExecuteNonQuery();command.CommandText="VACUUM";command.ExecuteNonQuery();command.CommandText="PRAGMA integrity_check";if(command.ExecuteScalar()?.ToString()!="ok")throw new InvalidDataException("GEX post-compaction integrity check failed");return new(CacheId,0,ReclaimedBytes:Math.Max(0,before-new FileInfo(path).Length),Compacted:true);
